  world.do('location.create', { name: 'Bakkie 1', kind: 'vehicle' });
  world.do('purchase_order.create', { supplierId: 2, orderedOn: '2026-11-01', currency: 'ZAR', lines: [line('Plywood sheets', 10000, 20000, 'sheet'), line('Screws box', 5000, 1000, 'box')] });
  const orderId = (((body(await run({ before: world.steps, ...get('accountant', '/engine/purchase-orders') })).result || {}).orders || [])[0] || {}).id;
  world.do('goods.receive', { orderId, receivedOn: '2026-11-05', lines: [{ lineNo: 1, quantityMilli: 4000 }, { lineNo: 2, quantityMilli: 5000 }] });
  const ordView = body(await run({ before: world.steps, ...get('accountant', `/engine/records/document/${orderId}`) })).result || {};
  const GR = ((ordView.relations || []).find((x) => x.role === 'receipt') || { ref: { id: 0 } }).ref.id;
  const recvHand = (extra = {}) => ({ itemId: 1, locationId: 1, quantityMilli: 10000, receivedOn: '2026-11-06', unitCostMinor: 20000, ...extra });
  const recvLine = (extra = {}) => ({ itemId: 1, locationId: 1, quantityMilli: 4000, receivedOn: '2026-11-06', receipt: { documentId: GR, lineNo: 1 }, ...extra });
  const stocked = ext(world); stocked.do('stock.receive', recvHand());                                                 // 10 sheets by hand at R200.00 each: value R2,000.00
  const stockOf = async (steps, q = '', role = 'accountant') => (body(await run({ before: steps, ...get(role, `/engine/stock${q}`) })).result || {});
  const itemsOf = async (steps, q = '', role = 'accountant') => (body(await run({ before: steps, ...get(role, `/engine/items${q}`) })).result || {});
  const ledgerOf = async (steps, itemId, role = 'accountant') => (body(await run({ before: steps, ...get(role, `/engine/stock/ledger?itemId=${itemId}`) })).result || {});
  const plyOf = (rep) => ((rep.stock || []).find((r) => r.itemId === 1) || {});

  // ---- 1. PERMISSIONS ------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
  check(['owner', 'accountant', 'admin'].every((r) => ['stock.manage', 'stock.move', 'stock.read', 'stock.value'].every((p) => has(r, p))), 'owner, accountant and admin may manage, move, read and see the value of stock');
  const mat = (r) => member(r).caps.includes('can_know_materials'), price = (r) => member(r).caps.includes('can_know_material_prices');
  check(['sales', 'installer'].every((r) => !has(r, 'stock.manage') && has(r, 'stock.move') === mat(r) && has(r, 'stock.read') === mat(r) && has(r, 'stock.value') === price(r)), 'field staff (the legacy materials capability) may read stock and PROPOSE moves, never manage it; costs and values only with the legacy material-prices capability');
  check(STOCK_CAPS.every((c) => eng.capabilities.CAPABILITY_IDS.includes(c)), 'the eleven stock capabilities exist in the engine');

  // ---- 2. ITEMS AND LOCATIONS: facts, each with its event ------------------------------------------------------------------------------------------------------------------------------------------------
  let r = await run({ before: [world.steps[0], world.steps[1]], ...propose('accountant', 'item.create', { sku: 'PLY-18', name: 'Plywood 18mm sheet', unit: 'sheet', reorderLevelMilli: 5000 }, 'Add plywood as a stock item') });
  check(status(r) === 200 && body(r).status === 'held' && touchesNoFact(r) && added(r, 'eng_event') === 0, 'proposing an item is HELD and records nothing');
  const ip = ext(seq()); ip.do('party.create', { kind: 'organisation', name: 'Timber Supplies', roles: ['supplier'] }); const iid = ip.prop('item.create', { sku: 'PLY-18', name: 'Plywood 18mm sheet', unit: 'sheet', reorderLevelMilli: 5000, reorderQtyMilli: 20000, preferredSupplierId: 2 });
  r = await run({ before: ip.steps, ...confirm('accountant', iid) });
  check(status(r) === 200 && added(r, 'eng_item') === 1 && added(r, 'eng_event') === 2 && added(r, 'eng_stock_move') === 0, `approving it records ONE item and its event (and the execution), and no stock (${status(r)})`);
  let it = await itemsOf(world.steps); const ply = (it.items || []).find((x) => x.sku === 'PLY-18') || {};
  check(ply.id === 1 && ply.name === 'Plywood 18mm sheet' && ply.unit === 'sheet' && ply.active === true && ply.quantityMilli === 0 && ply.reorderLevelMilli === 5000 && ply.belowReorder === true && it.count === 2, 'finding lists it: plywood, in sheets, active, none on hand, and below its reorder level of 5 (nothing is on hand)');
  const rv = ext(world); rv.do('item.revise', { itemId: 1, name: 'Plywood 18mm board', reorderLevelMilli: 2000, preferredSupplierId: null });
  const ply2 = ((await itemsOf(rv.steps)).items || []).find((x) => x.sku === 'PLY-18') || {};
  check(ply2.name === 'Plywood 18mm board' && ply2.reorderLevelMilli === 2000, 'revising an item changes what is shown (derived from its events) while its code and unit stay what they were');
  const off = ext(world); off.do('item.revise', { itemId: 1, active: false });
  check(((await itemsOf(off.steps, '?active=true')).items || []).length === 1 && ((await itemsOf(off.steps, '?active=false')).items || []).length === 1, 'an item can be made inactive, and finding by active works');
  r = await run({ before: [...off.steps], ...propose('accountant', 'stock.receive', recvHand()) }); check(status(r) === 409 && body(r).error === 'invalid_state' && /no longer active/.test(String(body(r).message || '')) && touchesNoFact(r), 'stock cannot be moved for an inactive item');
  const badItems = [[{ sku: 'X', name: 'x', unit: 'u', colour: 'blue' }, 'a field nobody declared'], [{ name: 'x', unit: 'u' }, 'no code'], [{ sku: ' ', name: 'x', unit: 'u' }, 'a blank code'], [{ sku: 'x'.repeat(41), name: 'x', unit: 'u' }, 'a code over 40 characters'], [{ sku: 'X', name: 'x' }, 'no unit'], [{ sku: 'X', name: 'x', unit: 'u', reorderLevelMilli: -1 }, 'a negative reorder level'], [{ sku: 'X', name: 'x', unit: 'u', reorderQtyMilli: 0 }, 'a reorder quantity of zero'], [{ sku: 'X', name: 'x', unit: 'u', reorderLevelMilli: 1.5 }, 'a fractional reorder level'], [null, 'no payload at all']];
  for (const [payload, why] of badItems) { r = await run({ before: world.steps, ...propose('accountant', 'item.create', payload) }); check(status(r) === 422 && body(r).error === 'invalid_payload' && touchesNoFact(r), `${why} is refused at the door as invalid_payload`); }
  r = await run({ before: world.steps, ...propose('accountant', 'item.create', { sku: 'PLY-18', name: 'Another', unit: 'sheet' }) }); check(status(r) === 409 && body(r).error === 'duplicate' && touchesNoFact(r), 'the same code twice is refused as a duplicate');
  r = await run({ before: world.steps, ...propose('accountant', 'item.create', { sku: 'NEW-1', name: 'x', unit: 'u', preferredSupplierId: 1 }) }); check(status(r) === 409 && body(r).error === 'invalid_state', 'a preferred supplier who is only a customer is refused');
  for (const [payload, why] of [[{ itemId: 1 }, 'nothing to change'], [{ itemId: 1, colour: 'x' }, 'a field nobody declared'], [{ itemId: 1, active: 'no' }, 'active that is not true or false'], [{ itemId: 'a', name: 'x' }, 'an item number that is text']]) { r = await run({ before: world.steps, ...propose('accountant', 'item.revise', payload) }); check(status(r) === 422 && body(r).error === 'invalid_payload', `revising with ${why} is refused as invalid_payload`); }
  r = await run({ before: world.steps, ...propose('accountant', 'item.revise', { itemId: 99, name: 'x' }) }); check(status(r) === 404, 'revising an item that does not exist is refused as not_found');
  for (const role of ['sales', 'installer']) for (const [cap, payload] of [['item.create', { sku: 'Z', name: 'z', unit: 'u' }], ['item.revise', { itemId: 1, name: 'z' }], ['location.create', { name: 'Z', kind: 'site' }]]) { r = await run({ before: world.steps, ...propose(role, cap, payload) }); check(status(r) === 403 && touchesNoFact(r), `${role} may not ${cap}: refused 403, nothing recorded`); }
  r = await run({ before: world.steps, ...propose('accountant', 'location.create', { name: 'main STORE', kind: 'warehouse' }) }); check(status(r) === 409 && body(r).error === 'duplicate', 'a location name already used (in any letter case) is refused');
  for (const [payload, why] of [[{ name: 'X', kind: 'garage' }, 'a kind nobody declared'], [{ name: '', kind: 'site' }, 'no name'], [{ name: 'X', kind: 'site', colour: 1 }, 'a field nobody declared']]) { r = await run({ before: world.steps, ...propose('accountant', 'location.create', payload) }); check(status(r) === 422 && body(r).error === 'invalid_payload', `a location with ${why} is refused`); }
  check(((await stockOf(world.steps)).locations || []).map((l) => l.name).join() === 'Main store,Bakkie 1', 'the locations are Main store and Bakkie 1');

  // ---- 3. RECEIVE ------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
  r = await run({ before: world.steps, ...propose('accountant', 'stock.receive', recvHand(), 'Ten sheets of plywood into the main store at R200 each') });
  check(status(r) === 200 && body(r).status === 'held' && touchesNoFact(r), 'proposing a receipt into stock is HELD and records nothing');
  check(JSON.stringify(r.writes || {}).includes('200000'), 'the approval is shown the value the engine worked out (R2,000.00)');
  const rp = ext(world); const rpId = rp.prop('stock.receive', recvHand());
  r = await run({ before: rp.steps, ...confirm('accountant', rpId) });
  check(status(r) === 200 && added(r, 'eng_stock_move') === 1 && added(r, 'eng_event') === 2 && added(r, 'eng_money_movement') === 0 && added(r, 'eng_document') === 0, `approving it records ONE stock movement and its event, no money and no document (${status(r)})`);
  let st = await stockOf(stocked.steps); let p1 = plyOf(st);
  check(p1.quantityMilli === 10000 && p1.valueMinor === 200000 && p1.averageCostMinor === 20000 && p1.belowReorder === false && (p1.locations || []).length === 1 && p1.locations[0].locationName === 'Main store' && p1.locations[0].quantityMilli === 10000, '10 sheets are on hand at Main store, worth R2,000.00 at an average of R200.00, and no longer below the reorder level');
  let lg = await ledgerOf(stocked.steps, 1); const m1 = (lg.moves || [])[0] || {};
