  check(m1.explained && m1.explained.contract === 'stock.receive' && m1.explained.approvedBy === 'accountant@example.com' && Number.isInteger(m1.explained.captureId) && Number.isInteger(m1.explained.interpretationId) && Number.isInteger(m1.explained.proposalId), 'it is EXPLAINED: what was said, what was understood, which proposal, who approved it and under which contract');
  const fromGr = ext(world); fromGr.do('stock.receive', recvLine());
  st = await stockOf(fromGr.steps); p1 = plyOf(st); lg = await ledgerOf(fromGr.steps, 1);
  check(p1.quantityMilli === 4000 && p1.valueMinor === 80000 && lg.moves[0].sourceDocumentId === GR && lg.moves[0].sourceLineNo === 1, 'stock received FROM the goods receipt line takes that line\'s cost (R200.00): 4 sheets worth R800.00, and the movement points at the receipt line it came from');
  r = await run({ before: fromGr.steps, ...propose('accountant', 'stock.receive', recvLine({ quantityMilli: 1 })) }); check(status(r) === 409 && body(r).error === 'invalid_state' && /already been put into stock/.test(String(body(r).message || '')) && touchesNoFact(r), 'the receipt line brought in 4 and all 4 are in stock: one more thousandth is refused, and the message says why');
  const part = ext(world); part.do('stock.receive', recvLine({ quantityMilli: 1500 }));
  r = await run({ before: part.steps, ...propose('accountant', 'stock.receive', recvLine({ quantityMilli: 2501 })) }); check(status(r) === 409 && body(r).error === 'invalid_state' && /only 2\.5 can be/.test(String(body(r).message || '')), 'after 1.5 of the 4 are stocked, 2.501 is refused and the message says only 2.5 can be');
  r = await run({ before: part.steps, ...propose('accountant', 'stock.receive', recvLine({ quantityMilli: 2500 })) }); check(status(r) === 200 && body(r).status === 'held', 'but 2.5 (exactly the rest) is fine');
  const recvRefusals = [
    [recvHand({ unitCostMinor: undefined }), 'invalid_payload', 'no cost and no goods receipt line'], [recvLine({ unitCostMinor: 20000 }), 'invalid_payload', 'a cost AND a goods receipt line (one source of cost)'], [recvHand({ quantityMilli: 0 }), 'invalid_payload', 'a quantity of zero'], [recvHand({ quantityMilli: 1.5 }), 'invalid_payload', 'a fractional quantity'],
    [recvHand({ unitCostMinor: -1 }), 'invalid_payload', 'a negative cost'], [recvHand({ receivedOn: '2026-02-30' }), 'invalid_payload', 'a date that does not exist'], [recvHand({ colour: 'x' }), 'invalid_payload', 'a field nobody declared'], [recvHand({ itemId: 99 }), 'not_found', 'an item that does not exist'], [recvHand({ locationId: 99 }), 'not_found', 'a location that does not exist'],
    [recvLine({ receipt: { documentId: 99999, lineNo: 1 } }), 'not_found', 'a goods receipt that does not exist'], [recvLine({ receipt: { documentId: 1, lineNo: 1 } }), 'invalid_state', 'a document that is not a goods receipt (invoice 1)'], [recvLine({ receipt: { documentId: GR, lineNo: 9 } }), 'invalid_input', 'a goods receipt line that does not exist'],
    [recvLine({ itemId: 2 }), 'invalid_input', 'an item in boxes against a receipt line in sheets'], [recvLine({ receivedOn: '2026-11-04' }), 'invalid_input', 'stock received before the goods arrived'],
  ];
  for (const [payload, code, why] of receiveRefusals(recvRefusals)) { r = await run({ before: world.steps, ...propose('accountant', 'stock.receive', payload) }); check(body(r).error === code && touchesNoFact(r) && added(r, 'eng_event') === 0, `${why} is refused at the door as ${code} (${status(r)} ${body(r).error}) and records nothing`); }
  function receiveRefusals(x) { return x; }
  r = await run({ before: world.steps, ...propose('accountant', 'stock.receive', recvHand({ quantityMilli: 1_000_000_000_000, unitCostMinor: 1_000_000_000_000 })) }); check(body(r).error === 'invalid_input' && touchesNoFact(r), 'a quantity and cost whose value would not fit in a whole number is refused (no overflow)');
  for (const role of ['sales', 'installer']) { r = await run({ before: world.steps, ...propose(role, 'stock.receive', recvHand()) }); check(status(r) === 403 && touchesNoFact(r), `${role} may not put goods into stock`); }
  r = await kit.route({ env: ENV, seed: kit.seedReceivables(kit.ALL_CAPABILITIES), ...propose('accountant', 'stock.receive', recvHand()) }); check(status(r) === 409 && body(r).error === 'capability_unavailable' && touchesNoFact(r), 'a business without the capability is told so');
  r = await run({ before: [...rp.steps, confirm('accountant', rpId)], ...confirm('accountant', rpId) }); check(status(r) !== 200 && added(r, 'eng_stock_move') === 0, 'approving the same proposal twice never receives twice');
  const dupe = ext(world); const a1 = dupe.prop('stock.receive', recvLine({ quantityMilli: 3000 })); const a2 = dupe.prop('stock.receive', recvLine({ quantityMilli: 3000 })); dupe.ok(a1);
  r = await run({ before: dupe.steps, ...confirm('accountant', a2) }); check(status(r) === 409 && added(r, 'eng_stock_move') === 0, 'two people stocking 3 of the 4 sheets that arrived: the second approval is refused, so a goods receipt line can never be over-stocked');

  const staleV = ext(world); staleV.do('stock.receive', recvHand()); const sv1 = staleV.prop('stock.issue', { itemId: 1, locationId: 1, quantityMilli: 2000, issuedOn: '2026-11-08', reason: 'use' }); staleV.do('stock.receive', recvHand({ quantityMilli: 10000, unitCostMinor: 40000, receivedOn: '2026-11-07' }));
  r = await run({ before: staleV.steps, ...confirm('accountant', sv1) });
