  const iss = ext(stocked); iss.do('stock.issue', is());
  st = await stockOf(iss.steps); p1 = plyOf(st); lg = await ledgerOf(iss.steps, 1); const im = lg.moves[1] || {};
  check(p1.quantityMilli === 7000 && p1.valueMinor === 140000 && p1.averageCostMinor === 20000 && im.kind === 'issue' && im.direction === 'out' && im.valueMinor === 60000 && im.reason === 'job' && im.jobRef === 'Mokoena lounge', 'issuing 3 of 10 sheets leaves 7 worth R1,400.00; the issue carries its cost, R600.00 (3 at the R200.00 average), and the job it was for');
  check(im.explained && im.explained.contract === 'stock.issue' && im.explained.approvedBy === 'accountant@example.com', 'the issue is explained as well');
  const mixed = ext(world); mixed.do('stock.receive', recvHand({ quantityMilli: 10000, unitCostMinor: 20000, receivedOn: '2026-11-06' })); mixed.do('stock.receive', recvHand({ quantityMilli: 10000, unitCostMinor: 30000, receivedOn: '2026-11-07' })); mixed.do('stock.issue', is({ quantityMilli: 5000 }));
  p1 = plyOf(await stockOf(mixed.steps)); lg = await ledgerOf(mixed.steps, 1);
  check(p1.quantityMilli === 15000 && lg.moves[2].valueMinor === 125000 && p1.valueMinor === 375000 && p1.averageCostMinor === 25000, 'the average moves with the receipts: 10 at R200.00 and 10 at R300.00 average R250.00, so issuing 5 takes R1,250.00 and leaves 15 worth R3,750.00');
  const later = ext(mixed); later.do('stock.receive', recvHand({ quantityMilli: 10000, unitCostMinor: 50000, receivedOn: '2026-11-09' }));
  lg = await ledgerOf(later.steps, 1); check(lg.moves[2].valueMinor === 125000, 'a LATER receipt at a higher price never changes the cost an earlier issue was stamped with');
  const res = ext(world); res.do('stock.receive', recvHand({ quantityMilli: 3000, unitCostMinor: 3333 })); res.do('stock.receive', recvHand({ quantityMilli: 2000, unitCostMinor: 3334, receivedOn: '2026-11-07' })); res.do('stock.issue', is({ quantityMilli: 2000 })); res.do('stock.issue', is({ quantityMilli: 3000, jobRef: 'second job' }));
  lg = await ledgerOf(res.steps, 1); p1 = plyOf(await stockOf(res.steps, '?itemId=1'));
  check(lg.moves[2].valueMinor === 6667 && lg.moves[3].valueMinor === 10000 && p1.quantityMilli === 0 && p1.valueMinor === 0, 'rounding never leaves a residue: 5 units worth R166.67, issue 2 (R66.67), issue the last 3 (exactly the remaining R100.00): zero quantity is exactly zero value');
  r = await run({ before: stocked.steps, ...propose('accountant', 'stock.issue', is({ quantityMilli: 10001 })) }); check(status(r) === 409 && body(r).error === 'invalid_state' && /Only 10 sheet/.test(String(body(r).message || '')) && touchesNoFact(r), 'issuing more than is there is refused, and the message says how much is');
